<template>
  <div class="min-h-screen bg-slate-50 dark:bg-slate-900 p-1">
    <div class="px-2 py-1 flex items-center justify-between">
      <div class="flex-grow">
        <NavigationComponent :breadcrumbs="[
          { label: 'Mantenimiento de Clientes', path: '/app/mCustomer' },
        ]" />
      </div>
      <div class="w-[5%] flex ml-4  justify-end">
        <createButton @click="openCreateModal" />
      </div>
    </div>

    <div class="px-2 pb-1">
      <TableMaintenance :items="dataItem" @edit="handleEdit" @delete="handleDelete" />
    </div>

    <FormCreateComponent class="backdrop-blur-md" v-if="showCreateModal" :show="showCreateModal" @close="closeCreateModal"
      @save="handleCreate" />

    <FormUpdateComponent class="backdrop-blur-md" v-if="showUpdateModal" :show="showUpdateModal" :clientData="selectedCustomer"
      @close="closeUpdateModal" @update="handleUpdate" />
  </div>
</template>

<script setup>
import TableMaintenance from '@/features/customer/components/TableMaintenance.vue'
import NavigationComponent from '@/components/ui/head/NavigationComponent.vue'
import FormCreateComponent from '../components/FormCreateComponent.vue'
import FormUpdateComponent from '../components/FormUpdateComponent.vue'
import createButton from '@/components/ui/button/createButton.vue'
import { ref, getCurrentInstance, onMounted } from 'vue'
import { allCustomer, deleteCustomer, createCustomerRoot, updateCustomerRoot, listCustomer, createCustomer, updateCustomer } from '../services/customerService'

import { useAuthStore } from '@/features/auth/stores/authStore'

const auth = useAuthStore()

const role = auth.user?.role
const dataItem = ref()
const isLoading = ref(false)
const errorMsg = ref('')
const selectedCustomer = ref({})
const showCreateModal = ref(false)
const showUpdateModal = ref(false)
const bus = getCurrentInstance()?.appContext.config.globalProperties.$bus

const listTranformer = async () => {
  isLoading.value = true
  errorMsg.value = ''
  try {
    let response

    if (role === 'ROOT') {
      response = await allCustomer()
    } else if (role === 'FACTORY') {
      response = await listCustomer()
    } else {
      throw new Error('Rol no autorizado')
    }

    if (response) {
      dataItem.value = response.data
    }
  } catch (e) {
    errorMsg.value = e?.response?.data?.message || 'Error al cargar clientes'
    bus?.emit?.('error', errorMsg.value)
  } finally {
    isLoading.value = false
  }
}


const openCreateModal = () => {
  showCreateModal.value = true
}

const closeCreateModal = () => {
  showCreateModal.value = false
}

const handleCreate = async (formData) => {
  isLoading.value = true
  errorMsg.value = ''

  try {


    let response

    if (role === 'ROOT') {
      response = await createCustomerRoot(formData)
    } else if (role === 'FACTORY') {
      response = await createCustomer(formData)
    } else {
      throw new Error('Rol no autorizado')
    }

    if (response) {
      bus?.emit?.('success', 'Transformador creado correctamente')
      closeCreateModal()
      listTranformer()
    }

  } catch (e) {
    errorMsg.value = e?.response?.data?.message || 'Error al crear transformador'
    bus?.emit?.('error', errorMsg.value)
  } finally {
    isLoading.value = false
  }
}


const openUpdateModal = (clientData) => {
  selectedCustomer.value = { ...clientData }
  showUpdateModal.value = true
}

const closeUpdateModal = () => {
  showUpdateModal.value = false
  selectedCustomer.value = {}
}



const handleUpdate = async (updateData) => {

  isLoading.value = true
  errorMsg.value = ''

  try {

    let response
 
    if (role === 'ROOT') {
      response = await updateCustomerRoot(updateData.data, updateData.uid)
    } else if (role === 'FACTORY') {
      response = await updateCustomer(updateData.data, updateData.uid)
    } else {
      throw new Error('Rol no autorizado')
    }


    if (response) {
      bus?.emit?.('success', 'Transformador actualizado correctamente')
      closeUpdateModal()
      listTranformer()
    }
  } catch (e) {
    errorMsg.value = e?.response?.data?.message || 'Error al actualizar transformador'
    bus?.emit?.('error', errorMsg.value)
  } finally {
    isLoading.value = false
  }
}


const handleEdit = (transformer) => {
  openUpdateModal(transformer)
}


const handleDelete = async (payload) => {
  isLoading.value = true
  errorMsg.value = ''
  try {
    const response = await deleteCustomer(payload.uid)

    if (response) {
      bus?.emit?.('success', 'Se eliminó correctamente')
      listTranformer()
    }
  } catch (e) {
    errorMsg.value = e?.response?.data?.message || 'error al eliminar transformadores'
    bus?.emit?.('error', errorMsg.value)
  } finally {
    isLoading.value = false
  }
}

onMounted(() => {
  listTranformer()
})
</script>